func (q *Queries) SetFile(ctx context.Context, arg SetFileParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setFile,
		arg.Outcome,
		arg.Reason,
		arg.Hold,
		arg.Confirmed,
		arg.Probe,
		arg.Quality,
		arg.Cut,
		arg.ReleaseName,
		arg.RootID,
		arg.Dest,
		arg.SentTransfer,
		arg.SentOrder,
		arg.PlacedBy,
		arg.FileID,
		arg.SourceRemovedAt,
		arg.ImportID,
		arg.Position,
		arg.Was,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

